import { gsap } from 'gsap';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { Group, PointLight, Vector3 } from 'three/tsl';
export default function createNode(config, ctx) {
  const { Group: ThreeGroup, PointLight: ThreePointLight } = ctx.THREE;
  const root = new ThreeGroup();
  root.name = config.id ?? 'node';
  root.userData.handlers = {};
  root.userData._primitives = [];
  root.userData._timelines = [];

  // Load GLB mesh
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    root.add(gltf.scene);
    root.userData._gltf = gltf;
    // Preserve original Y for hover animation
    root.userData._originalY = root.position.y;
  });

  // Accent rim light
  const accentColor = (config.colors && config.colors.accent) || '#ff2a38';
  const rimLight = new ThreePointLight(accentColor, 0.6, 0, 2);
  rimLight.position.set(0, 0, 2);
  root.add(rimLight);
  root.userData._rimLight = rimLight;

  // Cinematic primitives
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const { name, params } = prim;
      if (typeof ctx.primitives[name] === 'function') {
        const instance = ctx.primitives[name](root, params);
        root.userData._primitives.push(instance);
      }
    }
  }

  // Hover rise‑in effect
  const riseIn = (enter) => {
    const origY = root.userData._originalY ?? 0;
    const targetY = enter ? origY + 0.15 : origY;
    const tl = gsap.timeline({ onComplete: () => {
      const idx = root.userData._timelines.indexOf(tl);
      if (idx >= 0) root.userData._timelines.splice(idx, 1);
    } });
    tl.to(root.position, { y: targetY, duration: 0.7, ease: 'power3.out' });
    root.userData._timelines.push(tl);
  };
  root.userData.handlers.hover = () => riseIn(true);
  root.userData.handlers.hoverout = () => riseIn(false);

  // Click emit
  root.userData.handlers.click = () => {
    ctx.emit('hub-features.select');
  };

  // Cleanup
  root.userData.cleanup = () => {
    // Dispose GLB resources
    if (root.userData._gltf) {
      root.userData._gltf.scene.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }
    // Cleanup primitives
    for (const p of root.userData._primitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    // Kill timelines
    for (const tl of root.userData._timelines) {
      tl.kill();
    }
    // Dispose rim light
    if (root.userData._rimLight && typeof root.userData._rimLight.dispose === 'function') {
      root.userData._rimLight.dispose();
    }
    // Remove all children
    root.clear();
  };

  return root;
}
